class BrowserHistory:
    def __init__(self, homepage: str):
        self.history = [homepage]
        self.curr = 0
        self.validLen = 1

    def visit(self, url: str) -> None:
        if self.curr == self.validLen - 1 and self.validLen == len(self.history):
            self.history.append(url)
        else:
            self.validLen = self.curr + 1
            self.history[self.curr + 1] = url

        self.curr += 1
        self.validLen += 1

    def back(self, steps: int) -> str:
        if steps > self.validLen - 1 or steps > self.curr:
            self.curr = 0
        else:
            self.curr -= steps
        return self.history[self.curr]

    def forward(self, steps: int) -> str:
        if steps > self.validLen -1 or steps > self.validLen - self.curr - 1:
            self.curr = self.validLen -1
        else:
            self.curr += steps
        return self.history[self.curr]


